window.renderChancayCase=(t,href)=>{
 const base='assets/chancay/';
 const still=(n,h)=>`<img src="${base}article-${n}.webp" width="750" height="${h}" alt="${t('钱凯港2025成绩单，静态内容第','Chancay 2025 results, section ')}${n}${t('部分','')}" decoding="async">`;
 const motion=(name,zh,en)=>`<img class="chancay-motion" data-animation="${base}${name}.webp" data-poster="${base}${name}-still.webp" src="${base}${name}-still.webp" width="710" height="620" alt="${t(zh,en)}" decoding="async">`;
 const artwork=()=>still(1,2320)+motion('container','集装箱作业成绩单动态图','Animated container operations chart')+motion('bulk','散杂货作业成绩单动态图','Animated breakbulk operations chart')+still(2,2850)+still(3,2000)+still(4,1790)+motion('roro','滚装船作业成绩单动态图','Animated roll-on/roll-off operations chart')+motion('loading','拆箱及装箱作业成绩单动态图','Animated container stuffing and unstuffing chart')+still(5,1596);
 const annual=window.renderAnnualCase(t,href);
 let device=annual.slice(annual.indexOf('<div class="annual-device">'),annual.indexOf('</section><dialog'));
 device=device.replace(/<div class="annual-screen"[\s\S]*?<\/div><div class="annual-homebar"/,`<div class="annual-screen" tabindex="0" role="region" aria-label="${t('可滚动阅读的钱凯港成绩单','Scrollable Chancay results artwork')}">${artwork()}</div><div class="annual-homebar"`);
 return `<section class="project-header"><div class="project-title"><h1 class="page-title">${t('钱凯港<br>2025 成绩单','Port of Chancay<br>2025 Results')}</h1></div><div class="project-info"><dl><div><dt>${t('项目 / 品牌','Project / Brand')}</dt><dd>${t('中远海运港口有限公司','COSCO SHIPPING Ports Limited')}</dd></div><div><dt>${t('内容年度','Reporting year')}</dt><dd>2025</dd></div><div><dt>${t('服务类别','Category')}</dt><dd>${t('数据内容与信息可视化','Data & Information Design')}</dd></div><div><dt>${t('服务内容','Services')}</dt><dd>${t('业绩长图 / 动态图表 / 公众号视觉','Results infographic / Animated charts / WeChat design')}</dd></div></dl><div class="project-description"><span class="number">${t('项目介绍','About the project')}</span><p>${t('以公众号长图梳理钱凯港的年度运营表现，将业务数据、航线网络与港口场景串联为连续的阅读叙事。红蓝色彩建立信息层级，四处动态图表结合折线、数字与船舶图像，让不同业务板块的运营趋势更直观。','A long-form WeChat infographic connecting Chancay’s annual operating results, shipping network and port environments. Red and blue structure the information, while four animated charts combine lines, figures and vessel imagery to bring different operating trends into focus.')}</p></div></div></section><section class="annual-stage chancay-stage">${device}<div class="annual-note"><p>${t('在手机内上下滚动，查看完整作品。','Scroll inside the phone to explore the complete work.')}</p><p class="annual-language-note">${t('作品画面保留原始中文。','The original artwork is presented in Chinese.')}</p><div class="annual-actions"><button type="button" data-annual-open>${t('展开阅读','Expand artwork')} ↗</button><button type="button" data-chancay-motion aria-pressed="true">${t('暂停动态','Pause animation')}</button><button type="button" data-annual-reset>${t('回到开头','Start again')} ↑</button></div><div class="annual-progress" role="progressbar" aria-label="${t('阅读进度','Reading progress')}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"><span></span></div><small class="annual-percent">0%</small></div></section><section class="chancay-motion-details"><div class="chancay-motion-copy"><h2>${t('让运营趋势，动态呈现。','Operating trends,<br>in motion.')}</h2><p>${t('四组动态图表分别呈现集装箱、散杂货、滚装船与拆装箱作业表现。<br>以红蓝折线区分业务指标，结合数字与船舶图像，让月度变化与全年成果更直观。','Four animated charts present container, breakbulk, roll-on/roll-off and container stuffing operations. Red and blue lines distinguish metrics, while figures and vessel imagery make monthly changes and annual results easier to follow.')}</p></div><div class="chancay-motion-grid"><figure>${motion('container','集装箱作业成绩单动态图','Animated container operations chart')}<figcaption>${t('集装箱作业','Container operations')}</figcaption></figure><figure>${motion('bulk','散杂货作业成绩单动态图','Animated breakbulk operations chart')}<figcaption>${t('散杂货作业','Breakbulk operations')}</figcaption></figure><figure>${motion('roro','滚装船作业成绩单动态图','Animated roll-on/roll-off operations chart')}<figcaption>${t('滚装船作业','Roll-on/roll-off operations')}</figcaption></figure><figure>${motion('loading','拆箱及装箱作业成绩单动态图','Animated container stuffing and unstuffing chart')}<figcaption>${t('拆箱 / 装箱作业','Unstuffing / stuffing operations')}</figcaption></figure></div></section><section class="chancay-qr-footer"><div class="chancay-qr-area">${new URLSearchParams(location.search).get('id')==='chancay'?`<a href="https://mp.weixin.qq.com/s/xRosGzMzYKkEL90-7ZUTHw" target="_blank" rel="noopener noreferrer" aria-label="钱凯港2025成绩单公众号原文"><img src="assets/chancay/wechat-qr.png" alt="扫描二维码查看钱凯港2025成绩单" width="200" height="200" style="display:block;width:160px;height:160px;opacity:1!important;transform:none!important;margin:auto"></a>`:`<div class="chancay-qr-placeholder" role="img" aria-label="${t('公众号二维码预留位置','Space reserved for the WeChat QR code')}"><span>${t('二维码待补充','QR code to follow')}</span></div>`}<p class="chancay-qr-label">${t('扫一扫，在公众号浏览','Scan to view on WeChat')}</p></div></section><dialog class="annual-dialog chancay-dialog" aria-label="${t('钱凯港完整作品','Complete Chancay artwork')}"><div class="annual-dialog-top"><span>${t('钱凯港 · 2025 成绩单','Chancay · 2025 Results')}</span><button type="button" data-annual-close>${t('关闭','Close')} ×</button></div><div class="annual-expanded">${artwork()}</div></dialog><section class="next-project"><a href="${href('work')}">↖ ${t('返回全部案例','Back to all projects')}</a><a href="${href('project','&id=annual2025')}"><span>${t('下一个项目','Next project')}</span><strong>${t('中远海运港口 · 2025 业绩成绩单','COSCO SHIPPING Ports · 2025 Results')} ↗</strong></a></section>`;
};
document.addEventListener('DOMContentLoaded',()=>{
 const stage=document.querySelector('.chancay-stage');if(!stage)return;
 const button=stage.querySelector('[data-chancay-motion]'),en=document.documentElement.lang==='en';
 const images=[...document.querySelectorAll('.chancay-motion')];
 let playing=!matchMedia('(prefers-reduced-motion: reduce)').matches;
 const visible=new Set();
 function update(){
  button.setAttribute('aria-pressed',String(playing));button.textContent=playing?(en?'Pause animation':'暂停动态'):(en?'Play animation':'播放动态');
  images.forEach(img=>{const src=playing&&!document.hidden&&visible.has(img)?img.dataset.animation:img.dataset.poster;if(img.getAttribute('src')!==src)img.src=src});
 }
 const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>entry.isIntersecting?visible.add(entry.target):visible.delete(entry.target));update()},{threshold:.02});
 images.forEach(img=>observer.observe(img));button.addEventListener('click',()=>{playing=!playing;update()});
 document.addEventListener('visibilitychange',update);update();
});
